#include "abc/core.hpp"
#include "../src/encoding_metadata.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sstream>
namespace {
unsigned checks=0,failures=0;
void check(bool ok,std::string_view message){++checks;if(!ok){++failures;if(failures<15)std::cerr<<"FAIL "<<message<<'\n';}}
std::vector<std::vector<std::string>> rows(std::string_view name){std::ifstream f(std::filesystem::path(abc::from_utf8(__FILE__)).parent_path()/"fixtures"/std::string(name));if(!f)throw std::runtime_error("Missing encoding metadata fixture");std::vector<std::vector<std::string>> result;std::string line;while(std::getline(f,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();if(line.empty()||line[0]=='#')continue;std::vector<std::string> r;std::size_t a=0;for(;;){auto b=line.find('\t',a);r.push_back(line.substr(a,b-a));if(b==line.npos)break;a=b+1;}result.push_back(std::move(r));}return result;}
std::string run(const abc::Program& p,const std::string& input){std::istringstream in(input);std::ostringstream out;abc::execute(p,in,out);return out.str();}
std::uint64_t hash(std::uint64_t h,std::int32_t value){for(unsigned k=0;k<4;++k){h^=static_cast<std::uint8_t>(static_cast<std::uint32_t>(value)>>(k*8));h*=1099511628211ULL;}return h;}
void reference(){using M=abc::EncodingMethod;const auto properties=abc::compile("begin var cp:integer;Read(cp);var e:=Encoding.GetEncoding(cp);Writeln(e.WebName);Writeln(e.BodyName);Writeln(e.HeaderName);Writeln(e.WindowsCodePage);Writeln(e.IsSingleByte);Writeln(e.IsBrowserDisplay);Writeln(e.IsBrowserSave);Writeln(e.IsMailNewsDisplay);Writeln(e.IsMailNewsSave);Writeln(e.IsReadOnly);end.");auto data=rows("encoding-metadata-reference.tsv");check(data.size()==140,"All metadata pages");for(const auto& r:data){check(r.size()==13,"Metadata row width");std::string expected;for(unsigned k=1;k<=10;++k)expected+=r[k]+"\n";check(run(properties,r[0])==expected,"All public invariant property values and static return types");}
 for(const auto& r:rows("encoding-max-models.tsv")){check(r.size()==9,"Max-size model and actual public API fingerprints");const auto cp=static_cast<std::uint16_t>(std::stoul(r[0]));std::uint64_t bh=14695981039346656037ULL,ch=bh;for(std::int32_t n=0;n<65536;++n){bh=hash(bh,std::get<std::int32_t>(abc::encoding_metadata_value(cp,M::max_byte_count,n,{})));ch=hash(ch,std::get<std::int32_t>(abc::encoding_metadata_value(cp,M::max_char_count,n,{})));}check(bh==std::stoull(r[7],nullptr,16),"Actual exhaustive max-byte outcome fingerprint");check(ch==std::stoull(r[8],nullptr,16),"Actual exhaustive max-char outcome fingerprint");}
 const auto count=abc::compile("begin var cp,m,n:integer;Read(cp,m,n);var e:=Encoding.GetEncoding(cp);Write('before');\nif m=0 then Write(e.GetMaxByteCount(n)) else Write(e.GetMaxCharCount(n));end.");auto boundaries=rows("encoding-max-boundaries.tsv");for(const auto& r:boundaries){std::istringstream in(r[0]+" "+r[1]+" "+r[2]);std::ostringstream out;try{abc::execute(count,in,out);check(r[3]!="ArgumentOutOfRangeException"&&out.str()=="before"+r[3],"Public count boundary");}catch(const abc::Error& e){check(r[3]=="ArgumentOutOfRangeException"&&e.code=="E_ARGUMENT"&&!e.russian.empty()&&e.location.line==2&&out.str()=="before","Bilingual negative/overflow boundary with source and output");}}check(boundaries.size()==6980,"Every independently recorded count boundary");
}
void validation(){for(const auto& source:{"begin var e:=Encoding.UTF8;e.WebName:='x';end.","begin Write('bad');Writeln(Encoding.UTF8.IsSingleByte(1));end.","begin Writeln(Encoding.UTF8.GetMaxByteCount('1'));end.","begin var x:boolean:=Encoding.UTF8.WindowsCodePage;end.","begin Writeln(Encoding.UTF8.GetMaxCharCount);end."}){try{abc::compile(source);check(false,"Invalid static API accepted");}catch(const abc::Error& e){check(!e.russian.empty(),"Invalid property/count use rejected before execution");}}
 for(const auto& suffix:{"WebName","IsReadOnly","WindowsCodePage","GetMaxByteCount(-1)"}){auto p=abc::compile("begin var e:Encoding;Write('before');\nWriteln(e."+std::string(suffix)+");end.");std::istringstream in;std::ostringstream out;try{abc::execute(p,in,out);check(false,"Nil metadata receiver accepted");}catch(const abc::Error& e){check(e.code=="E_NIL"&&!e.russian.empty()&&e.location.line==2&&out.str()=="before","Nil receiver precedes count validation");}}
 auto p=abc::compile("begin Writeln(Encoding.UTF8.GetMaxByteCount(3));end.");for(unsigned mode=0;mode<5;++mode){auto bad=p;for(auto& op:bad.code)if(op.op==abc::Op::encoding_call&&op.operand==static_cast<std::size_t>(abc::EncodingMethod::max_byte_count)){if(mode==0)op.operand=999;else if(mode==1)op.type=abc::Type::integer;else if(mode==2)op.operand=static_cast<std::size_t>(abc::EncodingMethod::web_name);else if(mode==3)op.operand=static_cast<std::size_t>(abc::EncodingMethod::bytes_string);else op.operand=static_cast<std::size_t>(abc::EncodingMethod::is_single_byte);}try{abc::verify(bad);check(false,"Forged Encoding signature accepted");}catch(const abc::Error& e){check(e.code=="E_BYTECODE"&&!e.russian.empty(),"Forged argument/result/method metadata rejected");}}
}
}
int main(){try{reference();validation();}catch(const std::exception& e){check(false,e.what());}std::cout<<checks<<" encoding metadata checks, "<<failures<<" failures\n";return failures?1:0;}